<?php
declare(strict_types=1); namespace App\Application\FinancialDistribution;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter}; use App\Application\Commissions\Statements\CommissionPayableLink; use App\Models\{CommissionAccrual,PartnerPayoutAttempt,PartnerPayoutRequest,PartnerStatement,User}; use Illuminate\Support\Facades\{Crypt,DB}; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class PayoutService { public function __construct(private AuditWriter$audit,private OutboxWriter$outbox,private DistributionEventWriter$events,private CommissionPayableLink$payable,private \App\Application\Commissions\Machine\CommissionLifecycleService$lifecycle){}
 public function request(PartnerStatement$s,array$d,User$actor):PartnerPayoutRequest{return DB::transaction(function()use($s,$d,$actor){$s=PartnerStatement::lockForUpdate()->findOrFail($s->id);if($s->status!=='PUBLISHED'||$d['amount_minor']<=0||$d['amount_minor']>$s->closing_balance_minor)throw ValidationException::withMessages(['amount_minor'=>__('wave6.payout_exceeds_available')]);if($e=PartnerPayoutRequest::where('tenant_id',$s->tenant_id)->where('idempotency_key',$d['idempotency_key'])->first())return$e;$reserved=PartnerPayoutRequest::where('partner_statement_id',$s->id)->whereIn('status',['REQUESTED','APPROVED','PROCESSING','PAID'])->sum('amount_minor');if($reserved+$d['amount_minor']>$s->closing_balance_minor)throw ValidationException::withMessages(['amount_minor'=>__('wave6.payout_exceeds_available')]);$p=PartnerPayoutRequest::create(['tenant_id'=>$s->tenant_id,'partner_id'=>$s->partner_id,'partner_statement_id'=>$s->id,'payout_number'=>'PAY-'.strtoupper(Str::random(10)),'amount_minor'=>$d['amount_minor'],'currency'=>$s->currency,'status'=>'REQUESTED','destination_type'=>$d['destination_type'],'destination_encrypted'=>Crypt::encryptString($d['destination']),'idempotency_key'=>$d['idempotency_key'],'requested_by'=>$actor->id]);$this->audit->record('partner_payout.requested','partner_payout_request',$p->id,['amount_minor'=>$p->amount_minor]);return$p;});}
 public function approve(PartnerPayoutRequest$p,User$actor):PartnerPayoutRequest{return$this->transition($p,'REQUESTED','APPROVED','APPROVED',$actor,['approved_by'=>$actor->id,'approved_at'=>now()],true);}
 public function markProcessing(PartnerPayoutRequest$p,array$d,User$actor):PartnerPayoutRequest{return DB::transaction(function()use($p,$d,$actor){$p=PartnerPayoutRequest::lockForUpdate()->findOrFail($p->id);if($p->status!=='APPROVED')throw ValidationException::withMessages(['payout'=>__('wave6.invalid_transition')]);$attempt=(int)PartnerPayoutAttempt::where('partner_payout_request_id',$p->id)->max('attempt_number')+1;PartnerPayoutAttempt::create(['partner_payout_request_id'=>$p->id,'attempt_number'=>$attempt,'provider'=>$d['provider'],'status'=>'SUBMITTED','request_hash'=>hash('sha256',$p->id.':'.$attempt.':'.$p->amount_minor),'attempted_at'=>now()]);$p->update(['status'=>'PROCESSING','processing_at'=>now()]);$this->events->write($p->tenant_id,'PARTNER_PAYOUT',$p->id,'APPROVED','PROCESSING','SUBMITTED',$actor);return$p->refresh();});}
 public function complete(PartnerPayoutRequest$p,array$d,User$actor):PartnerPayoutRequest{return DB::transaction(function()use($p,$d,$actor){$p=PartnerPayoutRequest::lockForUpdate()->findOrFail($p->id);if($p->status!=='PROCESSING')throw ValidationException::withMessages(['payout'=>__('wave6.invalid_transition')]);$attempt=PartnerPayoutAttempt::where('partner_payout_request_id',$p->id)->latest('attempt_number')->lockForUpdate()->firstOrFail();$covered=[];$attempt->update(['status'=>'SUCCEEDED','provider_reference'=>$d['provider_reference']]);$p->update(['status'=>'PAID','paid_at'=>now()]);CommissionAccrual::where('tenant_id',$p->tenant_id)->where('partner_id',$p->partner_id)->where('status','VESTED')->orderBy('available_at')->lockForUpdate()->get()->reduce(function($remaining,$a)use(&$covered){$take=min($remaining,max(0,$a->vested_minor-$a->paid_minor));if($take){$a->increment('paid_minor',$take);$covered[]=$a;}return$remaining-$take;},$p->amount_minor);$this->payable->settlePayout($p,$actor->id);/* REQ-COM-001: covered accruals PAYABLE → PAID; the only obligation settled is the statement's (settlePayout). */foreach($covered as$a)$this->lifecycle->settlePaid($a,'payout:'.$p->id,$actor);$this->events->write($p->tenant_id,'PARTNER_PAYOUT',$p->id,'PROCESSING','PAID','PROVIDER_CONFIRMED',$actor);$this->outbox->record('partner.payout.paid','partner_payout_request',$p->id,['payout_id'=>$p->id]);return$p->refresh();});}
 public function fail(PartnerPayoutRequest$p,array$d,User$actor):PartnerPayoutRequest{return DB::transaction(function()use($p,$d,$actor){$p=PartnerPayoutRequest::lockForUpdate()->findOrFail($p->id);if($p->status!=='PROCESSING')throw ValidationException::withMessages(['payout'=>__('wave6.invalid_transition')]);PartnerPayoutAttempt::where('partner_payout_request_id',$p->id)->latest('attempt_number')->lockForUpdate()->firstOrFail()->update(['status'=>'FAILED','failure_code'=>$d['failure_code'],'failure_message'=>$d['failure_message']??null]);$p->update(['status'=>'FAILED','failure_code'=>$d['failure_code']]);$this->events->write($p->tenant_id,'PARTNER_PAYOUT',$p->id,'PROCESSING','FAILED',$d['failure_code'],$actor);return$p->refresh();});}
 public function reverse(PartnerPayoutRequest$p,string$reason,User$actor):PartnerPayoutRequest{return DB::transaction(function()use($p,$reason,$actor){$p=PartnerPayoutRequest::lockForUpdate()->findOrFail($p->id);if($p->status!=='PAID')throw ValidationException::withMessages(['payout'=>__('wave6.invalid_transition')]);$remaining=$p->amount_minor;foreach(CommissionAccrual::where('tenant_id',$p->tenant_id)->where('partner_id',$p->partner_id)->where('paid_minor','>',0)->orderByDesc('available_at')->lockForUpdate()->get()as$a){$take=min($remaining,$a->paid_minor);if($take)$a->decrement('paid_minor',$take);$remaining-=$take;if($remaining===0)break;}if($remaining!==0)throw ValidationException::withMessages(['payout'=>__('wave6.reversal_unbalanced')]);$p->update(['status'=>'REVERSED','failure_code'=>$reason]);$this->payable->reversePayout($p,$actor->id);$this->events->write($p->tenant_id,'PARTNER_PAYOUT',$p->id,'PAID','REVERSED',$reason,$actor);$this->outbox->record('partner.payout.reversed','partner_payout_request',$p->id,['payout_id'=>$p->id]);return$p->refresh();});}
 private function transition(PartnerPayoutRequest$p,string$from,string$to,string$reason,User$actor,array$attrs,bool$separate=false):PartnerPayoutRequest{return DB::transaction(function()use($p,$from,$to,$reason,$actor,$attrs,$separate){$p=PartnerPayoutRequest::lockForUpdate()->findOrFail($p->id);if($p->status!==$from||($separate&&$p->requested_by===$actor->id))throw ValidationException::withMessages(['payout'=>__('wave6.maker_checker')]);$p->update(['status'=>$to,...$attrs]);$this->events->write($p->tenant_id,'PARTNER_PAYOUT',$p->id,$from,$to,$reason,$actor);$this->outbox->record('partner.payout.'.strtolower($to),'partner_payout_request',$p->id,['payout_id'=>$p->id]);return$p->refresh();});}
}
